"""Build human and machine-readable prescription records from audited notes."""
from pathlib import Path
import json
entries=[]
def add(id,title,url,location,status,assumptions,validity,variables,interpretation,implementation):
 entries.append(dict(id=id,title=title,url=url,reference_location=location,status=status,assumptions=assumptions,validity=validity,variables_units=variables,implementation_interpretation=interpretation,implementation=implementation,inspected_utc='2026-09-28'))
add('bra2008','Begelman, Rossi & Armitage (2008)','https://arxiv.org/abs/0711.4078','Sections 2.1-2.4; Eqs 1-14','implemented_luminosity_law','Radiation dominated convective envelope; low BH/envelope mass; unresolved central accretion flow','Hot optically thick envelope; do not apply the analytic photosphere scalings as an EOS','L erg/s, M g, rho g/cm^3, P dyn/cm^2; alpha dimensionless','Eq 3 is a selectable luminosity law. Fixed excision geometry is an additional QStarS approximation, not BRA equilibrium replication.','src/qstars/engine.py')
add('ball2011','Ball et al. (2011)','https://arxiv.org/abs/1102.5098','Sections 2.1-2.3, 4.1; Eqs 2,5,9-15,24-33; Table 1','implemented_reference_and_printed_law','BH-only Bondi radius; rho~r^-3/2 cavity; loaded polytrope','Reference n=2,3,4 polytropes; complete stellar tracks require different microphysics','xi and phi dimensionless; accretion g/s; radius cm','Eq 15 prints 4pi despite Eq 12 plus rB=2GM/cs^2 implying 16pi. Preserve printed mode; do not blend with QUEST. Table 1 stored as unreplicated target.','src/qstars/reference.py; src/qstars/engine.py')
add('dotan2011','Dotan, Rossi & Shaviv (2011)','https://arxiv.org/abs/1107.3562','Sections 3.2-3.4; Eqs 19-23,31-32','implemented_optional_launch_closure','Porous radiation-driven sonic boundary; empirical wind function W; photon-tiring cap','Only effective launch prescription, not a solved porous atmosphere/wind','mdot g/s, L erg/s, gas sound speed cm/s, W dimensionless','Use gas isothermal sound speed; gamma<=1 gives zero. Wind enthalpy and energy to escape are separately charged.','src/qstars/winds.py')
add('ball_thesis','Ball (2012) thesis','https://arxiv.org/abs/1207.5972','Chapters 2-5; Bondi and CDAF/ADAF boundaries','audited_not_full_evolution','Boundary choice changes the evolutionary sequence and its mass limit','No single universal quasi-star BH mass limit','M g, r cm, thermodynamic quantities CGS','Inspected boundary discussion and contents; thesis has 145 pages and was not audited line by line. Alternatives must remain explicit.','docs/literature.md')
add('fiacconi2016','Fiacconi & Rossi (2016)','https://arxiv.org/abs/1509.07511','Section 2.1; Eqs 1-3; wind coupling in Section 3','audited_not_implemented_wind_ode','Stationary spherical radiation-dominated wind; radiation enthalpy advection','Gas pressure negligible and wind base optically thick','mdot g/s, L erg/s, specific Bernoulli energy erg/g','Radiation enthalpy matters. A photon-tiring cap alone cannot reproduce these solutions; full transonic replication remains pending.','docs/literature.md; src/qstars/mass_transport.py (energy accounting only)')
add('coughlin2024','Coughlin & Begelman (2024)','https://arxiv.org/abs/2405.00084','Sections 2-3; Eqs 2-7,11-21; Figs 1,3,4','implemented_reference_odes','Radiation-dominated saturated inner convection matched to n=3 outer envelope','Dimensionless static structure; thin radiative layer approximation','xi, m, Ki dimensionless','Direct ODE integration distinguishes corrected Bondi and saturated families. Printed Ki=.46554 and mBH/Mi=.6321 correspond to x_tilde=1, not the stated entropy minimum near 1.015. Retain both and document discrepancy.','src/qstars/reference.py')
add('quest2025','Campbell, Santarelli & Caplan (2025)','https://arxiv.org/abs/2507.12651','Eqs 1-5; Fig 1; public code','audited','MESA EOS/opacity, ML1 convection, cavity, TOV correction','Full published run depends on MESA r24.03.1','CGS; epsilon, eta dimensionless','Early note Eq 3 lacks (1-epsilon) while using a BH growth convention. Later article and source code have it. No silent normalization correction.','docs/literature.md')
add('santarelli2025','Santarelli et al. (2025/2026)','https://arxiv.org/abs/2510.11772','Sections V-VI; Eqs 8,11-13; upstream implementation','implemented_eq11_law_only','Convection-limited accretion with explicit radiative efficiency; MESA full tracks','Luminosity law does not reproduce its moving cavity or saturated-convection boundary','mdot_BH=(1-epsilon)mdot_rest g/s','Named quest2025_eq11 uses 16pi and distinct rest/BH rates; upstream HEAD inspected at 671eb9b898b28c0d02a6a2455dacc0f5b269e280.','src/qstars/engine.py')
add('hassan2025','Hassan et al. (2025/2026)','https://arxiv.org/abs/2510.18301','Section 2.1, Eqs 5-6; Appendix A cubic','implemented_reference_cubic','Self-consistent Bondi radius including rho~r^-3/2 cavity','Below critical mass, choose small positive radius continuous as MBH tends to zero','rho g/cm^3, cs cm/s, N dimensionless','Solve Appendix A cubic directly for stability near zero BH mass; verified equivalent to printed Eq 6. An initial factor-of-two audit suspicion was retracted (Report 4). Full ~0.33 evolutionary limit remains unreplicated.','src/qstars/reference.py')
add('cantiello2025','Cantiello et al. (2025/2026)','https://arxiv.org/abs/2512.17997','Section 2.2, nonadiabatic GYRE analysis','audited_not_implemented','GYRE 8.1 nonadiabatic radial modes with fixed inner displacement and MESA microphysics','Linear stability results cannot be inferred from nonlinear solver failures','Eigenfrequency complex; periods time; growth rates inverse time','QStarS Mach or solver stops are domain/numerical exits, not a pulsational-instability diagnosis.','src/qstars/validity.py')
add('roman2026','Roman-Garza et al. (2026)','https://arxiv.org/abs/2603.21714','Section 2; Appendix A; Table B.1','audited_not_replicated','Cold net mass gain; MESA 25.10.1; nuclear evolution and GR progenitor; late extrapolation','Net-gain sequences do not establish separate feeding/wind thermodynamics','Mass solar masses, time yr, luminosity solar luminosities in tables','Do not equate prescribed net gain with a resolved simultaneous two-stream flow; do not mistake analytically extrapolated late evolution for a completed stellar run.','docs/literature.md')
add('begelman2026','Begelman & Dexter (2026)','https://arxiv.org/abs/2507.09085','Late-stage quasi-star structural and spectral discussion','audited_context','Saturated envelope assumptions and late BH-dominated evolution','Qualitative context; not a QStarS spectral prediction','CGS, solar mass where stated','Spectral interpretation requires atmosphere microphysics absent from this solver.','docs/literature.md')
add('atmosphere2026','Martins, Schaerer & Marques-Chaves (2026)','https://arxiv.org/abs/2605.12141','Abstract and atmosphere-model assumptions','audited_context','Expanding spherical non-LTE CMFGEN atmospheres','5000-12000 K atmosphere models; not interior LTE closure','T K, L solar luminosities','Grey flux temperature is not a synthetic spectrum or a validated wind photosphere.','docs/literature.md')
add('mesa_energy','MESA technical documentation, energy equation','https://docs.mesastar.org/en/latest/reference/controls.html#energy-eqn-option','dedt and eps_grav descriptions; MESA V section 3 Eq 8 cited there','audited_numerical_reference','Total-energy conservation and thermodynamic consistency are distinct from resolution convergence','Stellar evolution numerical practice','e erg/g, P dyn/cm^2, V_rho cm^3/g','Use independent energy residuals plus mesh/time convergence. The implementation derives its own spherical discrete work identity, not a transcription of MESA.','src/qstars/numerics.py; docs/equations.md')
add('mesa_install','MESA installation and upstream QUEST','https://docs.mesastar.org/en/latest/installation.html','Prerequisites, SDK, release pinning','audited_backend_decision','Validated microphysics requires versioned EOS/opacity/atmosphere infrastructure','MESA absent on available Mac; documented 20 GB installation and SDK dependencies','Not applicable','MESA is preferred for future full-envelope production fidelity. This development solver cannot replace MESA ionization microphysics. No production backend is claimed.','docs/mesa.md')
add('ideal_eos','Classical ideal-gas plus radiation thermodynamics','https://arxiv.org/abs/1107.3562','Dotan Eqs 21-23; first-law derivation in docs/equations.md','derived_and_tested','Nondegenerate fully ionized monatomic mixture in LTE; fixed composition','1e5 <= T <= 1e8 K, electron occupation < 0.1, Newtonian low compactness','P dyn/cm^2, u erg/g, s erg/g/K','Heat capacities, adiabatic exponents, and entropy derived consistently from the same EOS; arbitrary entropy zero explicitly fixed.','src/qstars/eos.py')
add('thomson','Electron-scattering opacity','https://arxiv.org/abs/0711.4078','Section 2.3; Thomson cross section times electrons per gram','derived_approximation','Fully ionized H/He mixture; scattering dominates; LTE/thermalization separately assumed','Hot diffuse envelope; no bound-free/free-free/negative hydrogen/line opacity','kappa=0.2(1+X) cm^2/g','No cool extrapolation admitted as validated physics. Optional external opacity tables strictly reject out-of-bounds values and require provenance.','src/qstars/opacity.py')
add('diffusion','Rosseland radiative diffusion','https://docs.mesastar.org/en/latest/reference/controls.html','Temperature-gradient controls; diffusion derivation in docs/equations.md','derived','Optically thick LTE; F=-ac/(3 kappa rho) grad(T^4)','Cell optical depth >=1; no resolved optically thin transfer','Flux erg/cm^2/s; luminosity erg/s','Backward-Euler diffusion shares exactly one flux per face; grey extrapolation is an optional outer closure.','src/qstars/transport.py')
add('mlt_lossless','Optically thick lossless mixing-length limit','https://arxiv.org/abs/2507.12651','ML1 reference in Section II; explicit derivation in docs/equations.md','optional_approximation','Local buoyant blobs, no radiative heat leakage; l=alpha Hp','Efficient optically thick convection; not full ML1 or time-dependent convection','cp erg/g/K; velocity cm/s; l cm','Use v^2=g delta l^2 (nabla-nabla_ad)/(8Hp), F=rho cp T v l (nabla-nabla_ad)/(2Hp), capped by P cs. Entropy contrast discretized consistently.','src/qstars/transport.py')
add('compatible_work','Compatible spherical mechanical work','https://cnls.lanl.gov/~shashkov/papers/comp.pdf','Compatible differencing principle; QStarS derivation in docs/equations.md','derived','Fixed shell masses during mechanical substep; midpoint pressure and velocity; spherical gravity quadrature','Smooth subsonic flow; no shock validation','Total energy erg; nodal velocity cm/s','Secant area and 1/(r_new r_old) gravity produce exact work cancellation; no energy residual compensation. Article discovered as methodological background; full PDF not audited.','src/qstars/numerics.py')
add('two_stream','Conservative boundary source-cell closure','https://arxiv.org/abs/1509.07511','First-law open-system derivation; compare wind Eq 3','derived_optional_approximation','Separate mass sources/sinks at first/last cell; comoving mixing; supplied enthalpy and entropy specified','Effective 1D boundary mixing; unresolved geometry, shocks, inflow momentum','Mass g, enthalpy erg/g, entropy erg/g/K','Differentiate discrete gravitational energy for boundary potential flux; central-potential work is separately recorded. Wind escape cost debits outward light once.','src/qstars/mass_transport.py')
add('remapping','Conservative overlap remapping','https://cnls.lanl.gov/~shashkov/papers/comp.pdf','QStarS finite-volume derivation in docs/equations.md','derived','Piecewise constant volume and total specific energy in mass coordinates','Smooth resolved states; remap changes entropy and hydrostatic residual','Mass g, volume cm^3, energy erg','New internal energy is remapped total energy minus new discrete gravity and kinetic energies. Reject negative internal energy; log entropy changes.','src/qstars/mesh.py')
p=Path('src/qstars/data');p.mkdir(parents=True,exist_ok=True)
registry={'schema_version':1,'audit_date':'2026-09-28','prescriptions':entries}
(p/'sources.json').write_text(json.dumps(registry,indent=2)+'\n')
lines=['# Source and prescription registry','','This register distinguishes implemented laws, derived numerical identities, optional approximations, and unimplemented published models. Primary PDFs are locally cached, excluded from redistribution, and hashed in `sources/acquisition.json`.','']
for x in entries:
 lines += [f"## {x['id']} — {x['title']}", '', f"[{x['title']}]({x['url']}) · {x['reference_location']}", '',f"- Status: `{x['status']}`",f"- Assumptions: {x['assumptions']}",f"- Domain: {x['validity']}",f"- Variables and units: {x['variables_units']}",f"- Interpretation: {x['implementation_interpretation']}",f"- Implementation: `{x['implementation']}`",'']
Path('docs/sources.md').write_text('\n'.join(lines)+'\n')
